import React, { createContext, useContext, useEffect, useMemo, useState } from 'react';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const raw = localStorage.getItem('auth:user');
    if (raw) {
      try { setUser(JSON.parse(raw)); } catch {}
    }
  }, []);

  useEffect(() => {
    if (user) localStorage.setItem('auth:user', JSON.stringify(user));
    else localStorage.removeItem('auth:user');
  }, [user]);

  const login = async ({ email }) => {
    // Placeholder password auth
    setUser({ name: email.split('@')[0], email });
  };

  const signup = async ({ fullName, email }) => {
    setUser({ name: fullName || email.split('@')[0], email });
  };

  const loginWithGoogle = async () => {
    // Placeholder Google auth
    setUser({ name: 'Google User', email: 'user@gmail.com', provider: 'google' });
  };

  const logout = () => setUser(null);

  const value = useMemo(() => ({ user, login, signup, loginWithGoogle, logout }), [user]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}
